.card .thumb img { width: 64px; height: 64px; object-fit: cover; border-radius: 8px; border: 1px solid #eee; display: block; }
.card .thumb .no-thumb { width: 64px; height: 64px; border-radius: 8px; background: #f0efe9; display: flex; align-items: center; justify-content: center; font-size: 22px; }
.card .body { flex: 1; min-width: 0; }
.card .name { font-size: 17px; font-weight: 700; }
.pending-badge { display: inline-block; background: #fdf3e7; color: #b45309; font-size: 12px; padding: 3px 10px; border-radius: 10px; }
.actions-row { display: flex; gap: 12px; margin-top: 8px; }
.actions-row a { font-size: 13px; }

