  <div class="company">{{ c.company or "" }}</div>
  {% if c.tagline %}<div class="tagline">{{ c.tagline }}</div>{% endif %}
  {% if c.mobile %}<div class="row">📱 <a href="tel:{{ c.mobile }}">{{ c.mobile }}</a></div>{% endif %}
