<body>
<h1>🔗 產業鏈媒合總覽</h1>
<div class="subtitle">每張上傳的名片，AI 都會判斷它適合補進哪條產業鏈的哪個角色，或組成一條新的產業鏈。「待招募」代表這個位置還缺人，歡迎上傳符合的名片來補位。</div>

<div class="nav">
  <a href="/">📇 搜尋名片</a>
  <a href="/upload">📸 上傳名片</a>
</div>

{% if not chains %}
<div class="empty">目前還沒有形成任何產業鏈，上傳第一張名片開始吧</div>
{% endif %}

{% for c in chains %}
<div class="chain-card">
  <div class="chain-name">{{ c.chain.name }}</div>
  <div class="chain-theme">{{ c.chain.core_theme or "" }}</div>
  <div class="role-list">
    {% for m in c.members %}
    {% set bni = m.bni_status or 'unknown' %}
    <div class="role {{ 'gap' if m.is_gap else 'filled' }} {{ 'bni-member' if (m.is_gap and bni=='bni_member') else '' }} {{ 'not-bni' if (m.is_gap and bni=='not_bni') else '' }}">
      <div class="role-name">{{ m.role_name }}</div>
      {% if m.is_gap %}
        {% if bni == 'bni_member' %}
        <div class="role-status bni-member">🔵 已是BNI會員{% if m.bni_note %}・{{ m.bni_note }}{% endif %}</div>
        {% elif bni == 'not_bni' %}
        <div class="role-status not-bni">🎯 非BNI會員(招募目標)</div>
        {% else %}
        <div class="role-status gap">⏳ 待招募（未確認）</div>
        {% endif %}
        {% if logged_in %}
        <div class="bni-controls">
          <form method="POST" action="/chain_member/{{ m.member_id }}/bni_status" style="display:inline;">
            <input type="hidden" name="bni_status" value="bni_member">
            <button type="submit" class="{{ 'active' if bni=='bni_member' else '' }}" style="color:#1f5fa8;">🔵已是會員</button>
          </form>
          <form method="POST" action="/chain_member/{{ m.member_id }}/bni_status" style="display:inline;">
            <input type="hidden" name="bni_status" value="not_bni">
            <button type="submit" class="{{ 'active' if bni=='not_bni' else '' }}" style="color:#b3261e;">🎯非會員</button>
          </form>
          {% if bni != 'unknown' %}
          <form method="POST" action="/chain_member/{{ m.member_id }}/bni_status" style="display:inline;">
            <input type="hidden" name="bni_status" value="unknown">
            <button type="submit">重置</button>
          </form>
          {% endif %}
        </div>
        {% endif %}
      {% else %}
      <div class="role-status filled">✅ {{ m.card_name or "（未辨識姓名）" }}{% if m.card_company %}・{{ m.card_company }}{% endif %}</div>
      {% endif %}
    </div>
    {% endfor %}
  </div>
</div>
{% endfor %}

