1	<!doctype html>
2	<html lang="zh-Hant">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>產業鏈媒合｜{{ card.name or "名片" }}</title>
7	<style>
8	  body { font-family: -apple-system, "Noto Sans TC", sans-serif; max-width: 620px; margin: 0 auto; padding: 16px; background: #f7f6f2; color: #222; }
9	  .back { display: block; margin-bottom: 14px; color: #1f3a5f; text-decoration: none; font-size: 14px; }
10	  .box { background: white; border-radius: 12px; padding: 18px; margin-bottom: 16px; box-shadow: 0 1px 3px rgba(0,0,0,.08); }
11	  .name { font-size: 20px; font-weight: 900; }
12	  .company { color: #444; margin: 2px 0 4px; }
13	  .chain-box { background: #f7f6f2; border-radius: 10px; padding: 14px; margin-bottom: 12px; }
14	  .chain-name { font-weight: 900; color: #1f3a5f; font-size: 16px; margin-bottom: 2px; }
15	  .chain-theme { color: #666; font-size: 13px; margin-bottom: 10px; }
16	  .role-me { display: inline-block; background: #1f3a5f; color: white; font-size: 12px; padding: 3px 10px; border-radius: 10px; margin-bottom: 10px; }
17	  .other-role { display: flex; justify-content: space-between; padding: 8px 10px; border-radius: 8px; margin-top: 6px; }
18	  .other-role.filled { background: #eef7ee; }
19	  .other-role.gap { background: #fdf3e7; }
20	  .other-name { font-size: 13px; font-weight: 700; }
21	  .other-status { font-size: 12px; }
22	  .other-status.filled { color: #2e7d32; }
23	  .other-status.gap { color: #b45309; }
24	  .empty { color: #888; text-align: center; padding: 30px 0; font-size: 14px; }
25	  .error { background: #fdecea; color: #b3261e; padding: 12px 14px; border-radius: 8px; font-size: 14px; }
26	</style>
27	</head>
28	<body>
29	<a class="back" href="/">← 回名片搜尋首頁</a>
30	
31	<div class="box">
32	  <div class="name">{{ card.name or "（未辨識姓名）" }} {% if card.title %}<span style="font-weight:400;color:#666;">・{{ card.title }}</span>{% endif %}</div>
33	  <div class="company">{{ card.company or "" }}</div>
34	</div>
35	
36	{% if match_error %}
37	<div class="error">⚠️ 媒合分析失敗：{{ match_error }}，可以重新整理這頁再試一次</div>
38	{% elif not analyzed %}
39	<div class="empty">這張名片還沒完成基本辨識，暫時無法分析產業鏈</div>
40	{% elif not chains_detail %}
41	<div class="empty">AI 判斷這張名片目前不適合放進任何產業鏈（可能專業描述太籠統），之後有更多相關名片進來可能會改變</div>
42	{% else %}
43	{% for item in chains_detail %}
44	<div class="chain-box">
45	  <div class="chain-name">🔗 {{ item.chain.chain_name }}</div>
46	  <div class="chain-theme">{{ item.chain.core_theme or "" }}</div>
47	  <div class="role-me">這張名片的角色：{{ item.chain.role_name }}</div>
48	  {% for m in item.other_members %}
49	  <div class="other-role {{ 'gap' if m.is_gap else 'filled' }}">
50	    <div class="other-name">{{ m.role_name }}</div>
51	    {% if m.is_gap %}
52	    <div class="other-status gap">⏳ 待招募</div>
53	    {% else %}
54	    <div class="other-status filled">✅ {{ m.card_name or "未知" }}{% if m.card_company %}・{{ m.card_company }}{% endif %}</div>
55	    {% endif %}
56	  </div>
57	  {% endfor %}
58	</div>
59	{% endfor %}
60	{% endif %}
61	
62	</body>
63	</html>
