def update_gap_bni_status(conn: sqlite3.Connection, member_id: int, bni_status: str, bni_note: str = "") -> None:
    """標記待招募缺口的BNI會員狀態：unknown(未確認)/bni_member(已是BNI會員)/
    not_bni(確定非BNI會員，真正的招募目標)。只對is_gap=1的缺口有意義。"""
    conn.execute(
        "UPDATE chain_members SET bni_status = ?, bni_note = ? WHERE id = ? AND is_gap = 1",
        (bni_status, bni_note or None, member_id),
    )
    conn.commit()


def card_already_in_chain(conn: sqlite3.Connection, chain_id: int, card_id: int) -> bool:
    row = conn.execute(
        "SELECT 1 FROM chain_members WHERE chain_id = ? AND card_id = ?", (chain_id, card_id)
    ).fetchone()

@app.route("/chain_member/<int:member_id>/bni_status", methods=["POST"])
@team_login_required
def chain_member_bni_status(member_id):
    bni_status = request.form.get("bni_status", "unknown")
    bni_note = (request.form.get("bni_note") or "").strip()
    if bni_status not in ("unknown", "bni_member", "not_bni"):
        bni_status = "unknown"
    conn = db.get_conn()
    db.update_gap_bni_status(conn, member_id, bni_status, bni_note)
    conn.close()
    return redirect(request.referrer or url_for("chains_page"))

