content.content:
1	<!doctype html>
2	<html lang="zh-Hant">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>產業鏈媒合｜{{ card.name or "名片" }}</title>
7	<style>
8	  body { font-family: -apple-system, "Noto Sans TC", sans-serif; max-width: 620px; margin: 0 auto; padding: 16px; background: #f7f6f2; color: #222; }
9	  .back { display: block; margin-bottom: 14px; color: #1f3a5f; text-decoration: none; font-size: 14px; }
10	  .box { background: white; border-radius: 12px; padding: 18px; margin-bottom: 16px; box-shadow: 0 1px 3px rgba(0,0,0,.08); }
11	  .name { font-size: 20px; font-weight: 900; }
12	  .company { color: #444; margin: 2px 0 4px; }
13	  .chain-box { background: #f7f6f2; border-radius: 10px; padding: 14px; margin-bottom: 12px; }
14	  .chain-name { font-weight: 900; color: #1f3a5f; font-size: 16px; margin-bottom: 2px; }
15	  .chain-theme { color: #666; font-size: 13px; margin-bottom: 10px; }
16	  .role-me { display: inline-block; background: #1f3a5f; color: white; font-size: 12px; padding: 3px 10px; border-radius: 10px; margin-bottom: 10px; }
17	  .other-role { display: flex; justify-content: space-between; align-items: center; padding: 8px 10px; border-radius: 8px; margin-top: 6px; flex-wrap: wrap; gap: 6px; }
18	  .other-role.filled { background: #eef7ee; }
19	  .other-role.gap { background: #fdf3e7; }
20	  .other-role.gap.bni-member { background: #eaf2fb; }
21	  .other-role.gap.not-bni { background: #fdecea; }
22	  .other-name { font-size: 13px; font-weight: 700; }
23	  .other-status { font-size: 12px; }
24	  .other-status.filled { color: #2e7d32; }
25	  .other-status.gap { color: #b45309; }
26	  .other-status.bni-member { color: #1f5fa8; }
27	  .other-status.not-bni { color: #b3261e; }
28	  .bni-controls { display: flex; gap: 4px; }
29	  .bni-controls button { padding: 3px 8px; font-size: 11px; border-radius: 6px; border: 1px solid #ccc; background: white; cursor: pointer; }
30	  .bni-controls button.active { border-color: currentColor; font-weight: 700; }
31	  .empty { color: #888; text-align: center; padding: 30px 0; font-size: 14px; }
32	  .error { background: #fdecea; color: #b3261e; padding: 12px 14px; border-radius: 8px; font-size: 14px; }
33	</style>
34	</head>
35	<body>
36	<a class="back" href="/">← 回名片搜尋首頁</a>
37	
38	<div class="box">
39	  <div class="name">{{ card.name or "（未辨識姓名）" }} {% if card.title %}<span style="font-weight:400;color:#666;">・{{ card.title }}</span>{% endif %}</div>
40	  <div class="company">{{ card.company or "" }}</div>
41	</div>
42	
43	{% if match_error %}
44	<div class="error">⚠️ 媒合分析失敗：{{ match_error }}，可以重新整理這頁再試一次</div>
45	{% elif not analyzed %}
46	<div class="empty">這張名片還沒完成基本辨識，暫時無法分析產業鏈</div>
47	{% elif not chains_detail %}
48	<div class="empty">AI 判斷這張名片目前不適合放進任何產業鏈（可能專業描述太籠統），之後有更多相關名片進來可能會改變</div>
49	{% else %}
50	{% for item in chains_detail %}
51	<div class="chain-box">
52	  <div class="chain-name">🔗 {{ item.chain.chain_name }}</div>
53	  <div class="chain-theme">{{ item.chain.core_theme or "" }}</div>
54	  <div class="role-me">這張名片的角色：{{ item.chain.role_name }}</div>
55	  {% for m in item.other_members %}
56	  {% set bni = m.bni_status or 'unknown' %}
57	  <div class="other-role {{ 'gap' if m.is_gap else 'filled' }} {{ 'bni-member' if (m.is_gap and bni=='bni_member') else '' }} {{ 'not-bni' if (m.is_gap and bni=='not_bni') else '' }}">
58	    <div class="other-name">{{ m.role_name }}</div>
59	    {% if m.is_gap %}
60	      {% if bni == 'bni_member' %}
61	      <div class="other-status bni-member">🔵 已是BNI會員{% if m.bni_note %}・{{ m.bni_note }}{% endif %}</div>
62	      {% elif bni == 'not_bni' %}
63	      <div class="other-status not-bni">🎯 非BNI會員(招募目標)</div>
64	      {% else %}
65	      <div class="other-status gap">⏳ 待招募（未確認）</div>
66	      {% endif %}
67	      {% if logged_in %}
68	      <div class="bni-controls">
69	        <form method="POST" action="/chain_member/{{ m.member_id }}/bni_status" style="display:inline;">
70	          <input type="hidden" name="bni_status" value="bni_member">
71	          <button type="submit" class="{{ 'active' if bni=='bni_member' else '' }}" style="color:#1f5fa8;">🔵已是會員</button>
72	        </form>
73	        <form method="POST" action="/chain_member/{{ m.member_id }}/bni_status" style="display:inline;">
74	          <input type="hidden" name="bni_status" value="not_bni">
75	          <button type="submit" class="{{ 'active' if bni=='not_bni' else '' }}" style="color:#b3261e;">🎯非會員</button>
76	        </form>
77	        {% if bni != 'unknown' %}
78	        <form method="POST" action="/chain_member/{{ m.member_id }}/bni_status" style="display:inline;">
79	          <input type="hidden" name="bni_status" value="unknown">
80	          <button type="submit">重置</button>
81	        </form>
82	        {% endif %}
83	      </div>
84	      {% endif %}
85	    {% else %}
86	    <div class="other-status filled">✅ {{ m.card_name or "未知" }}{% if m.card_company %}・{{ m.card_company }}{% endif %}</div>
87	    {% endif %}
88	  </div>
89	  {% endfor %}
90	</div>
91	{% endfor %}
92	{% endif %}
93	
94	</body>
95	</html>
